insert into CHB_INTERF_ERRODATA (DATAUUID,DATAID, INTERF_TYPE, FIRE_NAME, ORG_DATA,ERR_MSG, STATUS, UPDATE_USER, CREATE_USER, UPDATE_TIME, CREATE_TIME, WORKFLOW_ID, ORG_CODE, DEPT_CODE, CREATE_DEPT) select DATAUUID,DATAID, INTERF_TYPE, FIRE_NAME, ORG_DATA,ERR_MSG, STATUS, UPDATE_USER, CREATE_USER, UPDATE_TIME, CREATE_TIME, WORKFLOW_ID, ORG_CODE, DEPT_CODE, CREATE_DEPT from ( select TEMP.* from (
SELECT #{item.datauuid,jdbcType=VARCHAR} DATAUUID, #{item.dataid,jdbcType=VARCHAR} DATAID, #{item.interfType,jdbcType=VARCHAR} INTERF_TYPE, #{item.fireName,jdbcType=VARCHAR} FIRE_NAME, #{item.orgData,jdbcType=CLOB} ORG_DATA, #{item.errMsg,jdbcType=CLOB} ERR_MSG, #{item.status,jdbcType=VARCHAR} STATUS, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.workflowId,jdbcType=VARCHAR} WORKFLOW_ID, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, #{item.orgCode,jdbcType=VARCHAR} ORG_CODE, #{item.deptCode,jdbcType=VARCHAR} DEPT_CODE FROM DUAL
) TEMP where not exists (select 1 from CHB_INTERF_ERRODATA CII where CII.DATAID = TEMP.DATAID) ) de ;
UPDATE CHB_INTERF_ERRODATA as A, ( select DATAUUID,DATAID, INTERF_TYPE, FIRE_NAME, ORG_DATA,ERR_MSG, STATUS, UPDATE_USER, CREATE_USER, UPDATE_TIME, CREATE_TIME, WORKFLOW_ID, ORG_CODE, DEPT_CODE, CREATE_DEPT from ( select TEMP.* from (
SELECT #{item.datauuid,jdbcType=VARCHAR} DATAUUID, #{item.dataid,jdbcType=VARCHAR} DATAID, #{item.interfType,jdbcType=VARCHAR} INTERF_TYPE, #{item.fireName,jdbcType=VARCHAR} FIRE_NAME, #{item.orgData,jdbcType=CLOB} ORG_DATA, #{item.errMsg,jdbcType=CLOB} ERR_MSG, #{item.status,jdbcType=VARCHAR} STATUS, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.workflowId,jdbcType=VARCHAR} WORKFLOW_ID, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, #{item.orgCode,jdbcType=VARCHAR} ORG_CODE, #{item.deptCode,jdbcType=VARCHAR} DEPT_CODE FROM DUAL
) TEMP ) de ) AS B set A.* = B.* where exists (select 1 from CHB_INTERF_ERRODATA CII where CII.DATAID = TEMP.DATAID);

